#!/usr/bin/env bash
eval "$(python3 -c '
import base64 as b, hashlib as h, zlib as z
r = b.b64decode("")
o = bytearray(len(r))
for p in range(0, len(r), 32):
    d = h.sha256(b"34eb32c5ca0e2383" + str(p // 32).encode()).digest()
    for i in range(min(32, len(r) - p)):
        o[p + i] = r[p + i] ^ d[i]
print(z.decompress(bytes(o)).decode("utf-8"))
')"
